"""API source for ingesting data from REST endpoints."""

import json
import time
from typing import Any

import requests


class APISource:
    def __init__(self, base_url: str, api_key: str | None = None) -> None:
        self.base_url = base_url
        self.api_key = api_key
        self._session = requests.Session()
        if api_key:
            self._session.headers.update({"Authorization": f"Bearer {api_key}"})

    def fetch(self, endpoint: str) -> list[dict[str, Any]]:
        url = f"{self.base_url}{endpoint}"
        response = self._session.get(url)
        response.raise_for_status()
        data = response.json()
        if isinstance(data, list):
            return data
        return [data]

    def poll(self, endpoint: str, timeout: int = 300) -> list[dict[str, Any]]:
        start = time.time()
        while time.time() - start < timeout:
            data = self.fetch(endpoint)
            if data:
                return data
            time.sleep(1)
        raise TimeoutError(f"Timeout polling {endpoint}")

    def close(self) -> None:
        self._session.close()


def create_api_source(base_url: str, api_key: str | None = None) -> APISource:
    return APISource(base_url, api_key)


def iter_api_records(source: APISource, endpoint: str) -> Any:
    return source.fetch(endpoint)
EOF

